content.query:
// Incidents by severity over time
SecurityIncident
| where TimeGenerated {timeRange}
| summarize Count = count() by Severity, bin(TimeGenerated, 1d)
| order by TimeGenerated asc

// MITRE ATT&CK technique distribution
SecurityAlert
| where TimeGenerated {timeRange}
| mv-expand tactic = todynamic(Tactics)
| summarize Count = count() by tostring(tactic)
| order by Count desc

// Top alerting analytics rules
SecurityAlert
| where TimeGenerated {timeRange}
| summarize Count = count() by AlertName = DisplayName
| order by Count desc
| take 15
